        ["煞戎努斯"] = { mythicplus = [=[{rt8}Charonus{rt8}||[Unstable Singularity] gravity collapse pulls in—don't get sucked to center (stand between holes to resist); [Gravity Orb] kite into a hole to delete, dodge lines||[Cosmic Smash] marked cast, [Void Torrent] channel—prioritize interrupt; new [Dark Wave] dodge by movement||Spread your purple circles; tank takes [Aggregated Mass]]=] },
        ["法术风暴拉杰克斯"] = { mythicplus = [[{rt8}Spellstorm Rajaxx{rt8}||[Disruption Orb] marks a player with a silence orb for 15s—lead it away from the group.||Multi-hit AoE spellstorm; on death grants the matching buff; the orb carrier stays 15s away from the group.]] },
        ["焦躁的虚镰"] = { mythicplus = [[{rt8}Restless Void Scythe{rt8}||[Corrosive Essence] now hits only 2 players (was 5), a 12s corruption DoT—must dispel or avoid overlap.||Those corrupted spread for 12s, healer pre-casts; grab the matching arena buff along the route.]] },
