        ["原始毒蛇"] = { mythicplus = [[{rt8}Primitive Serpent{rt8}||Spread to avoid [Foul Spit] splash; keep range.||{rt1}Must interrupt/kill fast: [Piercing Shriek]—interrupt every cast.{rt1}||Watch the poison damage; melee stay out of the spit circle.]] },
        ["双牙掠夺者"] = { mythicplus = [[{rt8}Twin-Fang Pillager{rt8}||Immune to CC; tank turns its front [Venom Breath] away from the group and soaks [Double Strike]'s heavy hit; [Deadly Shot] hits two players—magic dispel or freedom.||{rt1}Must interrupt/kill fast: no hard interrupt available.{rt1}||Stay spread to avoid breath hitting multiple; melee stand behind.]] },
        ["仪式首领"] = { mythicplus = [[{rt8}Ritual Leader{rt8}||Immune to CC; before engaging, destroy the Corrupted Mist totem to stop the [Unstable Totem] pulse; [Dissect] hits the tank—use a damage-reduction.||{rt1}Must interrupt/kill fast: [Blood Sacrifice] deals raid-wide damage and applies a heal absorb—pre-cast heals.{rt1}||Healer: watch the absorb shield; spell dispel is available.]] },
        ["扭缠盘蛇"] = { mythicplus = [=[{rt8}The Writhing Coil{rt8}||[Withering Venom] casts 3 in a row—assign interrupts; during [Death Rattle] everyone run out to snap [Vine Bonds] triggering [Uncoiled], focus the [Uncoiled Serpent] image||[Revenge Rush] dodge [Burrow Charge] lines, keep [Venom Spray] frontal away from group; kited player don't get bitten||Tank takes [Tail Blade]; healer cover [Synchronized Venom] stacking with [Death Rattle]]=] },
        ["拉维"] = { mythicplus = [=[{rt8}Rav'i{rt8}||Keep Boss away from carcass piles so it can't eat fresh meat and trigger [Gluttony]; during [Scavenge] everyone step in [Filthy Guests] to break shield fast||[Triple Shot] spread, dodge [Regurgitate] acid lines; tank takes [Water Smash] melee; healer watch [Carrion Burst] stacks||[Regurgitate] cleanses disease on hit; otherwise dodge rocks and big circles]=] },
        ["祖尔加"] = { mythicplus = [=[{rt8}Zul'jan{rt8}||During [Fang Ritual] 4 players stand on the line between snake-heads and Boss to soak [Ritual Venom] stacks; [Blood Sacrifice] clear stacks via physical hits (stand in [Bone Cleaver] axe path)||Drop the poison water at the edge; dodge [Bone Cleaver] axe paths and [Axe Polisher]'s 3 thrown axes||Tank [Sundering] opens with DR and drops a blood pool; healer cover [Fang Empower] stacks]=] },
