        ["缚地守护者"] = { mythicplus = [[{rt8}Grounding Guardian{rt8}||[Grounding Brand] marks a random target—focus heal and cover with damage reduction.||{rt1}Must interrupt: don't miss its buff/control casts.{rt1}||Kill fast to reduce stacks.]] },
        ["毁灭唤风者"] = { mythicplus = [[{rt8}Destructive Windcaller{rt8}||[Lightning Storm] raid-wide AoE—pop DR; interrupt or spell-reflect fast casts.||{rt1}Must interrupt: lightning/thunder casts.{rt1}||Hold aggro on summoned adds.]] },
