        ["闪霜织寒者"] = { mythicplus = [[{rt8}Flashfrost Weaver{rt8}||Ranged interrupt [Frostbolt] to protect the tank; prioritize CC-kill.||{rt1}Must interrupt/dispel: [Ice Barrier]—else the target is CC-immune and shielded.{rt1}||With the barrier up, focus fire under damage-reduction coverage.]] },
        ["烈焰之咽"] = { mythicplus = [[{rt8}Flame Gullet{rt8}||Dodge [Flame Breath]'s front; tank pops DR for the [Flame Maw] DoT.||{rt1}Kill fast: below half health [Lava Blood] stacks make raid damage explode.{rt1}||Save cooldowns/bloodlust for after half health.]] },
