        ["腐化术士"] = { mythicplus = [[{rt8}Corrupting Warlock{rt8}||Immune to CC.||{rt1}[Curse of Doom] random debuff (dispel or stack to share; a dead player summons a Doomguard).{rt1}||[Drain Life] marks a target—defend or drop combat.||Prioritize CC/interrupt on the doom bolt; dispel or share the curse promptly; before 50% it gains a Dark Pact shield—burn through it.]] },
        ["利希尔·烬怒"] = { mythicplus = [=[{rt8}Lishir{rt8}||[Chaos Bolt] random target must interrupt (top priority); opening [Felhunter] fixates tank—tank separates it from Boss||[Demon Portal] teleports then [Cataclysmic Tide] casts—take the safe side door, clear trash before tide to avoid +100% haste||[Fel Blast] use spare interrupts; [Burning Fel] pulses—watch positioning]=] },
        ["亵渎魔像"] = { mythicplus = [[{rt8}Defiled Golem{rt8}||Immune to CC.||{rt1}[Profane Smash] is a heavy channel—healer pre-cast.{rt1}||[Fel Beam] fires a line at each player leaving a puddle—dodge.||Found before the last boss; tank eats the smash with DR, raid dodges fel beams.]] },
        ["歼灭者萨祖克斯"] = { mythicplus = [=[{rt8}Xathuux the Annihilator{rt8}||[Axe Toss] marks then spawns [Legion Axes] at edge—burn immediately or AoE ramps (must-kill)||[Fel Strike] frontal—tank face out; during [Fel Frenzy] Boss leaves [Burning Stride] fel puddles—tank kites slowly along edge using less than half the room||Raid dodge landing zones, save DR for the damage amp]=] },
