        ["决意化身"] = { mythicplus = [[{rt8}Resolute Avatar{rt8}||Immune to CC.||[Frozen Tomb] roots the whole group—break it or use freedom; [Shatter] is a high-damage AoE.||Stay spread to avoid chained freezes; step out of Shatter circles immediately; use freedom/icebreak to clear the root.]] },
        ["饥荒雕像"] = { mythicplus = [[{rt8}Famine Statue{rt8}||Summoned by [Hungry Spirit], immune to CC.||Focus it on spawn or it repeatedly casts [Endless Hunger] (~5-6s cast applying a debuff).||Dispel the curse debuff; healer prepare for [Feast of Suffering] channel damage.]] },
