        ["寒冬暴雪"] = { mythicplus = [[{rt8}Winter Blizzard{rt8}||Immune to CC.||[Biting Blizzard] pulses until killed; [Winter Hall] pushes players.||Prioritize killing it to stop the zone blizzard; use snow-free cover to dodge the wind; snow mounds no longer cause slipping.]] }
