        ["堕落的守护者"] = { mythicplus = [[{rt8}Fallen Guardian{rt8}||Immune to CC; [Earthstomp] is a 30-yard AoE + knockback—spread or hug the wall; [Shatter] the main tank soaks with damage reduction and takes increased damage.||{rt1}Must kill fast: uninterruptible; [Shatter] tank must pop DR.{rt1}||Focus fire; avoid hard-soaking when stacked with other big hits.]] },
        ["塞塔里斯的化身"] = { mythicplus = [=[{rt8}Avatar of Sethraliss{rt8}||Two phases: kill [Defiler] to lift healing lock, then heal the central Avatar to full to win; [Corrupted Life]/[Corruption Burst] orbs soaked by DPS walking in (healer don't)||[Twisted Hexxer] must interrupt [Flame Shock]; focus [Faithless Tormenter] and keep away from healer—below 25% the Avatar executes it for a heal, keep above 25% before finish||[Fallen Guardian] [Corrupting Strike] tank DR; in P2 clear the healer-chasing adds]=] },
        ["米利克萨"] = { mythicplus = [=[{rt8}Merektha{rt8}||[Serpentine Knot] roots 2 players—interrupt/stun to free and AoE them down fast; [Venom Spray] must interrupt, [Thundering Breath] move away to drop circle||Free teammates pinned by adds immediately; after [Burrow] kill hatched [Venomous Viper]/[Storm Adder], tank kites [Storm Adder] to edge for [Storm Catalyst] pool||[Lightning Bite] tank DR; after [Serpent Storm] knockback dodge ground circles, avoid Boss cross-path]=] },
