        ["扭曲的妖术师"] = { mythicplus = [[{rt8}Twisted Hexxer{rt8}||[Lurking Hex] marks a player, drops a circle then turns them into a frog—move out of the group and avoid [Hex Mud]; [Flame Shock] is interruptible.||{rt1}Must interrupt: Flame Shock.{rt1}||Immune to CC; dispel [Lurking Hex] before it expires to prevent the frog.]] },
        ["无信征服者"] = { mythicplus = [[{rt8}Faithless Conqueror{rt8}||[Mind Disruption] randomly curses a player with confusion—interrupt or dispel to clear.||{rt1}Must interrupt: Mind Disruption.{rt1}||Watch healer pressure when stacked with [Shadow Lash].]] },
        ["流沙猎手"] = { mythicplus = [[{rt8}Quicksand Hunter{rt8}||[Arrow Barrage] channels on a random target—use CC/interrupt to stop the damage; dodge [Sandblast Arrow] landing circles.||{rt1}Must interrupt/kill fast: stop [Arrow Barrage]'s channel with CC or interrupt.{rt1}||CC it before pulling to avoid barrage stacking with other damage.]] },
        ["无信折磨者"] = { mythicplus = [[{rt8}Faithless Torturer{rt8}||Focus fire; it locks onto a healer and stacks [Shadow Lash] to reduce healing—kill it fast and away from the healer.||{rt1}Must kill fast: burn the healer-locking torturer before the healing debuff stacks.{rt1}||Below 25% the avatar executes it for a heal—keep it above 25% before finishing.]] },
        ["风暴飞蛇"] = { mythicplus = [[{rt8}Storm Viper{rt8}||[Storm Catalyst] leaves a thunder pool—everyone get out; tank pops damage reduction during [Serpent's Storm Call] buff.||{rt1}Must interrupt: Storm Catalyst (leaves pool damage).{rt1}||Pull the snake to the edge or onto existing poison to reduce field clutter.]] },
        ["剧毒蝰蛇"] = { mythicplus = [[{rt8}Venomous Viper{rt8}||[Venom Spray] targets a random player—interrupt to avoid stacking poison; [Cell Poison] use poison cleanse or damage reduction.||{rt1}Must interrupt: Venom Spray.{rt1}||Keep poison pools away from the group; healer watch targeted poison damage.]] },
        ["加瓦兹特"] = { mythicplus = [=[{rt8}Galvazzt{rt8}||[Lightning Spire] spawns 3 each time; non-tank DPS stand between Boss and spire to block beams and stop charging; at full energy [Charged Burst] is near-wipe—all 3 beams must be blocked every wave||[Shock] tank kites Boss along the edge dropping water; [Shock Field] lands—everyone out of circle; rotate beam-soakers (take [Shock] vulnerability, don't soak twice)]=] }
