        ["薯蛙母"] = { mythicplus = [[{rt8}Taro Frogmother{rt8}||Immune to CC.||[Tongue Toss] flings the tank (terrain-kill risk); [Venom Spit] raid poison DoT; [Lay Eggs] hatches [Newtlings] (knockback).||Tank stay away from platform edge when tossed; healer dispel poison; AoE the eggs instantly so they don't hatch.]] },
        ["圣光猎手伊库兹"] = { mythicplus = [=[{rt8}Ikuzz the Light Hunter{rt8}||At full energy [Bloodthirsty Gaze] locks 1 player for 10s; the hunted runs along [Bloodthorn Roots] using Boss like a lawnmower to crush them (stepping on = rooted); [Verdant Stomp] knocks back then grows roots under everyone—cleave the roots at your feet||At 50% [Lightfrenzied] spikes movement—burn it down; others dodge thorns and don't get stomped into danger]=] },
        ["兹欧凯特"] = { mythicplus = [=[{rt8}Zikket{rt8}||[Bloom Essence] orbs drift toward Boss—soak all, never let Boss eat them (else shield + Radiant Burst); [Awakened Bloom] summons [Bloom Lashes]—push to dormant then finish with [Focused Light] to clear [Luminous Resin]||[Sapwood] pulses raid-wide; pull Boss to platform edge so resin doesn't clutter center||Prioritize interrupting/stunning adds that spawn]=] },
        ["光明众花"] = { mythicplus = [=[{rt8}Lightbloom Trinity{rt8}||Three share hp—AoE all together; [Light Arrow]/[Radiant Slash] must interrupt||[Bedrock Crusher] spawns [Fertile Soil]/[Blinding Light Bloom] beams—someone must stand in the beam/circle to block light or the flower stacks [Light Devoured] (+15% dmg/stack); tank + 2 step into circle first||[Thornblade] marks then [Thornfan] hits 3x/sec—marked player run out before popping DR]=] },
        ["翠绿林地守卫"] = { mythicplus = [[{rt8}Verdant Grove Guardian{rt8}||Immune to CC.||[Earthrend] marks the tank leaving a puddle; [Uproot] AoE heavy hit + knockback.||Tank drops the puddle outside the group; don't stand near cliffs/roots before the knockback.]] },
        ["灌木潜行者"] = { mythicplus = [[{rt8}Bramble Stalker{rt8}||[Thornblade] marks a random target with heavy bleed (8s).||Focus heal / clear bleed / personal damage reduction.]] },
        ["疯长多头蛇"] = { mythicplus = [[{rt8}Rampant Hydra{rt8}||Immune to CC.||[Lightjaw Beam] channels 3 random targets (line hurts allies); [Seed Volley] line marks.||Three spread outward so the beam doesn't cross allies; use vanish/shadowmeld to drop combat and avoid it; dodge lines.]] },
